// A synthetic plugin for PluginCallCostBenchmarks: the shape of a real source (search with paging,
// details) with a fixed amount of work and host calls per call, and no network.
var WORK = 2000;
function busy() { var s = 0; for (var i = 0; i < WORK; i++) s += Math.sqrt(i); return s; }
function item(i) {
  return new PlatformVideo({
    id: new PlatformID("Bench", "v" + i, plugin.config.id),
    name: "Video " + i, url: "https://bench.invalid/v/" + i, duration: 60 + i,
    thumbnails: new Thumbnails([new Thumbnail("https://bench.invalid/t/" + i + ".jpg", 1)]),
    author: new PlatformAuthorLink(new PlatformID("Bench", "a", plugin.config.id), "Author", "https://bench.invalid/a")
  });
}
function SearchPager(page) {
  var items = [];
  for (var i = 0; i < 30; i++) items.push(item(page * 30 + i));
  VideoPager.call(this, items, page < 50, { page: page });
}
SearchPager.prototype = Object.create(VideoPager.prototype);
SearchPager.prototype.nextPage = function () { busy(); bridge.isLoggedIn(); return new SearchPager(this.context.page + 1); };

source.enable = function () { busy(); bridge.isLoggedIn(); };
source.getHome = function () { return new SearchPager(0); };
source.search = function (query) { busy(); bridge.isLoggedIn(); log("search " + query); return new SearchPager(0); };
source.isChannelUrl = function () { return false; };
source.getChannel = function () { return null; };
source.getChannelContents = function () { return new SearchPager(0); };
source.isContentDetailsUrl = function (url) { return url.indexOf("https://bench.invalid/v/") === 0; };
source.getContentDetails = function (url) {
  busy(); bridge.isLoggedIn();
  var doc = domParser.parseFromString("<html><body><p class='d'>Description</p></body></html>", "text/html");
  var description = doc.querySelector(".d").textContent;
  return new PlatformVideoDetails({
    id: new PlatformID("Bench", url, plugin.config.id), name: "Details", url: url, description: description,
    thumbnails: new Thumbnails([]), author: new PlatformAuthorLink(new PlatformID("Bench", "a", plugin.config.id), "Author", "https://bench.invalid/a"),
    duration: 60, video: new VideoSourceDescriptor([])
  });
};
